CREATE TYPE "AdminRole" AS ENUM ('ADMIN', 'EDITOR');
CREATE TYPE "ProjectStatus" AS ENUM ('DRAFT', 'PUBLISHED', 'ARCHIVED');
CREATE TYPE "EnquiryStatus" AS ENUM ('NEW', 'IN_PROGRESS', 'RESOLVED', 'SPAM');
CREATE TYPE "RequestStatus" AS ENUM ('NEW', 'REVIEWING', 'CONTACTED', 'ACCEPTED', 'DECLINED', 'SPAM');
CREATE TABLE "Admin" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"name" TEXT NOT NULL,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"role" "AdminRole" NOT NULL DEFAULT 'EDITOR',"isActive" BOOLEAN NOT NULL DEFAULT true,"lastLoginAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Admin_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Service" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"title" TEXT NOT NULL,"slug" TEXT NOT NULL,"shortDescription" TEXT NOT NULL,"description" TEXT NOT NULL,"icon" TEXT,"imageUrl" TEXT,"features" TEXT[] DEFAULT ARRAY[]::TEXT[],"order" INTEGER NOT NULL DEFAULT 0,"isActive" BOOLEAN NOT NULL DEFAULT true,"isArchived" BOOLEAN NOT NULL DEFAULT false,"seoTitle" TEXT,"seoDescription" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Service_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Project" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"title" TEXT NOT NULL,"slug" TEXT NOT NULL,"clientName" TEXT,"summary" TEXT NOT NULL,"content" TEXT NOT NULL,"coverImageUrl" TEXT,"galleryImages" TEXT[] DEFAULT ARRAY[]::TEXT[],"technologies" TEXT[] DEFAULT ARRAY[]::TEXT[],"projectUrl" TEXT,"completionDate" TIMESTAMP(3),"order" INTEGER NOT NULL DEFAULT 0,"status" "ProjectStatus" NOT NULL DEFAULT 'DRAFT',"isFeatured" BOOLEAN NOT NULL DEFAULT false,"seoTitle" TEXT,"seoDescription" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"publishedAt" TIMESTAMP(3),CONSTRAINT "Project_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProjectService" ("projectId" UUID NOT NULL,"serviceId" UUID NOT NULL,CONSTRAINT "ProjectService_pkey" PRIMARY KEY ("projectId","serviceId"));
CREATE TABLE "Enquiry" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"name" TEXT NOT NULL,"email" TEXT NOT NULL,"phone" TEXT,"company" TEXT,"subject" TEXT NOT NULL,"message" TEXT NOT NULL,"status" "EnquiryStatus" NOT NULL DEFAULT 'NEW',"adminNotes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Enquiry_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProjectRequest" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"name" TEXT NOT NULL,"email" TEXT NOT NULL,"phone" TEXT,"company" TEXT,"projectType" TEXT,"projectSummary" TEXT NOT NULL,"budgetRange" TEXT,"desiredStartDate" TIMESTAMP(3),"timeline" TEXT,"attachmentUrl" TEXT,"status" "RequestStatus" NOT NULL DEFAULT 'NEW',"adminNotes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ProjectRequest_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProjectRequestService" ("projectRequestId" UUID NOT NULL,"serviceId" UUID NOT NULL,CONSTRAINT "ProjectRequestService_pkey" PRIMARY KEY ("projectRequestId","serviceId"));
CREATE TABLE "SiteSettings" ("id" INTEGER NOT NULL DEFAULT 1,"companyName" TEXT NOT NULL,"contactEmail" TEXT NOT NULL,"contactPhone" TEXT,"address" TEXT,"linkedInUrl" TEXT,"defaultSeoTitle" TEXT NOT NULL,"defaultSeoDescription" TEXT NOT NULL,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "SiteSettings_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Admin_email_key" ON "Admin"("email");
CREATE UNIQUE INDEX "Service_slug_key" ON "Service"("slug");
CREATE INDEX "Service_isActive_order_idx" ON "Service"("isActive","order");
CREATE UNIQUE INDEX "Project_slug_key" ON "Project"("slug");
CREATE INDEX "Project_status_order_idx" ON "Project"("status","order");
CREATE INDEX "Enquiry_status_createdAt_idx" ON "Enquiry"("status","createdAt");
CREATE INDEX "ProjectRequest_status_createdAt_idx" ON "ProjectRequest"("status","createdAt");
ALTER TABLE "ProjectService" ADD CONSTRAINT "ProjectService_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ProjectService" ADD CONSTRAINT "ProjectService_serviceId_fkey" FOREIGN KEY ("serviceId") REFERENCES "Service"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ProjectRequestService" ADD CONSTRAINT "ProjectRequestService_projectRequestId_fkey" FOREIGN KEY ("projectRequestId") REFERENCES "ProjectRequest"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ProjectRequestService" ADD CONSTRAINT "ProjectRequestService_serviceId_fkey" FOREIGN KEY ("serviceId") REFERENCES "Service"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
